import React from 'react';
import logoImg from '../assets/logo.png'; // ඔයාගේ ලෝගෝ එකේ path එක මෙතනට දෙන්න

export default function Navbar({ onLoginClick, isLoggedIn, setCurrentPage, currentPage }) {
  return (
    <header style={{
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      padding: '0 40px',
      backgroundColor: '#ffffff',
      borderBottom: '1px solid #e2e8f0',
      height: '70px',
      position: 'sticky',
      top: 0,
      zIndex: 100,
      fontFamily: 'sans-serif',
      boxSizing: 'border-box'
    }}>
      {/* 🖼️ AuraPen Logo Image */}
      <div style={{ display: 'flex', alignItems: 'center', cursor: 'pointer' }} onClick={() => setCurrentPage('Home')}>
        <img src={logoImg} alt="AuraPen Education" style={{ height: '42px', objectFit: 'contain' }} />
      </div>

      {/* Navigation Links */}
      <nav style={{ display: 'flex', gap: '30px' }}>
        {['Home', 'Classes', 'Teachers', 'About'].map((page) => (
          <span
            key={page}
            onClick={() => setCurrentPage(page)}
            style={{
              cursor: 'pointer',
              fontSize: '15px',
              fontWeight: currentPage === page ? '600' : '500',
              color: currentPage === page ? '#15803d' : '#475569'
            }}
          >
            {page}
          </span>
        ))}
      </nav>

      {/* Dashboard එකේ නැති වෙලාවට විතරක් Login Button එක පෙන්වනවා */}
      <div>
        {!isLoggedIn && (
          <button
            onClick={onLoginClick}
            style={{
              backgroundColor: '#15803d',
              color: '#ffffff',
              border: 'none',
              padding: '10px 22px',
              borderRadius: '8px',
              fontWeight: '600',
              cursor: 'pointer',
              fontSize: '14px'
            }}
          >
            Login
          </button>
        )}
      </div>
    </header>
  );
}
